import { TaskCompleted } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

test(covers(['usecase:complete_task', 'criterion:0001/persistencia-conclusao'], 'complete_task salva completed, publica TaskCompleted e falha para id ausente'), async () => {
  const t1 = Task.create('t1', 'pagar contas');
  t1.pullEvents();
  const storage = new Map<string, Task>([['t1', t1]]);
  const saved: Task[] = [];
  const published: unknown[][] = [];
  const repo: TaskRepository = { findById: async (id) => storage.get(id) ?? null, save: async (task) => { saved.push(task); storage.set(task.id, task); } };
  const ctx: UseCaseContext = { correlationId: 'corr-1', causationId: 'cause-1', publish: async (events) => { published.push([...events]); } };
  const useCase = new CompleteTask(repo);

  const output = await useCase.execute({ task_id: 't1' }, ctx);
  expect(output).toEqual({ task_id: 't1', status: 'completed' });
  expect(saved).toHaveLength(1);
  expect(saved[0]?.status).toBe('completed');
  expect(published).toHaveLength(1);
  expect(published[0]).toHaveLength(1);
  expect(published[0]?.[0]).toBeInstanceOf(TaskCompleted);
  expect((published[0]?.[0] as TaskCompleted).payload).toEqual({ taskId: 't1' });

  const act = () => useCase.execute({ task_id: 'missing' }, ctx);
  await expect(act()).rejects.toBeInstanceOf(DomainError);
  try {
    await act();
  } catch (error) {
    expect(error).toBeInstanceOf(DomainError);
    expect((error as DomainError).code).toBe('TASK_NOT_FOUND');
    return;
  }
  throw new Error('expected complete_task to throw');
});
